o Podcast Production benchmarks in Bahrain.', 'دليل تنفيذي من آي شوت حول معايير إنتاج البودكاست المرئي التنفيذي في البحرين.', 'Client Care', '{"media","client care","Manama","2026"}'::text[], 'Bader Ali', 'published', now() - interval '72 days', false, now() - interval '72 days', now()) ON CONFLICT (id) DO NOTHING;
