INSERT INTO cms.website_content (id, draft, published, previous, revision, published_at, updated_at) VALUES ('main', '{"company":{"nameEn":"ishoot Cinema Production S.P.C.","nameAr":"دار آي شوت للإنتاج السينمائي ذ.م.م","shortEn":"ishoot","shortAr":"آي شوت","taglineEn":"Cinema Production & Creative Media Studio","taglineAr":"استوديو الإنتاج السينمائي والإعلام الإبداعي","aboutEn":"Premier cinematic media production house in the Kingdom of Bahrain, crafting narrative-driven brand films, commercials, and aerial cinematography.","aboutAr":"دار إنتاج سينمائي رائدة في مملكة البحرين، متخصصة في صناعة الأفلام الإعلانية الوثائقية والتصوير الجوي السينمائي."},"hero":{"titleEn":"ishoot — Cinema Production & Creative Media Studio","titleAr":"آي شوت — استوديو الإنتاج السينمائي والإعلام الإبداعي","ctaLabelEn":"Explore ishoot","ctaLabelAr":"استكشف آي شوت"},"featuredServices":[{"code":"SVC-CIN","en":"Cinema Commercial Production","ar":"إنتاج الأفلام الإعلانية السينمائية","rate":3500},{"code":"SVC-DOC","en":"Brand Documentary Film","ar":"فيلم وثائقي للعلامة التجارية","rate":4800},{"code":"SVC-CAM","en":"ARRI / RED Cinema Package Rental","ar":"تأجير حزمة كاميرات آري وريد","rate":320},{"code":"SVC-COL","en":"Dolby Vision Color Grading Suite","ar":"جناح تلوين دولبي فيجن","rate":420}]}'::jsonb, '{"company":{"nameEn":"ishoot Cinema Production S.P.C.","nameAr":"دار آي شوت للإنتاج السينمائي ذ.م.م","shortEn":"ishoot","shortAr":"آي شوت","taglineEn":"Cinema Production & Creative Media Studio","taglineAr":"استوديو الإنتاج السينمائي والإعلام الإبداعي","aboutEn":"Premier cinematic media production house in the Kingdom of Bahrain, crafting narrative-driven brand films, commercials, and aerial cinematography.","aboutAr":"دار إنتاج سينمائي رائدة في مملكة البحرين، متخصصة في صناعة الأفلام الإعلانية الوثائقية والتصوير الجوي السينمائي."},"hero":{"titleEn":"ishoot — Cinema Production & Creative Media Studio","titleAr":"آي شوت — استوديو الإنتاج السينمائي والإعلام الإبداعي","ctaLabelEn":"Explore ishoot","cta